
const assert=require('node:assert/strict'),C=require('../js/core.js'),raw=require('../situations/adjustment-lj-koryan.js'),s=C.normalize(raw),{Attempt}=require('../js/playable.js');require('../js/course.js');
const test=(name,fn)=>{fn();console.log('PASS '+name);};
const fits=(board,a)=>C.cells(a.type,a.rotation).every(([x,y])=>a.x+x>=0&&a.x+x<10&&a.y+y>=-2&&a.y+y<board.length&&(a.y+y<0?'.':board[a.y+y][a.x+x])==='.');
test('NES Koryan reference is mirrored horizontally, including L/J handedness',()=>{
 const original=['.......SS.','SSSS..SSS.','SSSS..SSS.'];const board=C.compose(s.frames[0],18).slice(15).map(r=>r.map(c=>c==='.'?'.':'S').join(''));
 assert.deepEqual(board,original.map(r=>[...r].reverse().join('')));assert.equal(s.adjustment.adjusted.type,'J');assert.equal(s.adjustment.next.type,'L');assert.deepEqual(s.frames[0].motif.cells,[[3,16],[6,16],[3,17],[6,17]]);
});
test('default blocks the next L, while adjusted placements fit and cap the motif',()=>{
 const b=C.compose(s.frames[0],18),m=s.adjustment;assert(fits(b,m.default));assert(!fits(C.compose({board:b,active:m.default},18),m.next));assert(fits(b,m.adjusted));assert(fits(C.compose({board:b,active:m.adjusted},18),m.next));
 const occupied=new Set([m.adjusted,m.next].flatMap(a=>C.cells(a.type,a.rotation).map(([x,y])=>[x+a.x,y+a.y].join(','))));for(const[x,y]of s.frames[0].motif.cells)assert(occupied.has([x===3?4:5,y].join(',')));
});
test('default and adjusted ghosts, next cue, pair highlight and final motif blink are separate steps',()=>{
 assert.equal(s.frames[0].active.y,C.spawn(s.frames[0].active.type).y);assert(s.frames[0].motif);for(const i of [1,2,3])assert.equal(s.frames[i].active.y,0);
 assert.equal(C.frameAt(s.frames[1],0).ghost.label,'Default');assert.equal(C.frameAt(s.frames[1],13).ghost,undefined);assert.equal(C.frameAt(s.frames[2],0).nextPreviewVisible,true);assert.equal(C.frameAt(s.frames[2],13).nextPreviewVisible,false);assert.equal(s.frames[3].ghost.label,'Adjusted');assert.equal(s.frames.find(f=>f.placementHighlights).placementHighlights.length,2);assert.equal(C.frameAt(s.frames.find(f=>f.placementHighlights),13).placementHighlights,undefined);assert(s.frames.at(-1).motif);
});
test('both piece animations and the continuous clean playback avoid stack collisions',()=>{
 for(const f of s.frames.filter(f=>f.animate)){const b=C.compose({...f,active:undefined},18);for(let t=0;t<=f.ticks;t++)assert(fits(b,C.frameAt(f,t).active));}
 const clean=global.TetrisCourse.clean(s);assert(clean.frames.some(f=>f.active?.type==='J'));assert(clean.frames.some(f=>f.active?.type==='L'));for(const f of clean.frames){if(f.active)assert(fits(C.compose({...f,active:undefined},18),f.active));assert(!f.ghost&&!f.motif&&!f.placementHighlights);}
});
test('adjustment metadata and every lesson cue survive compact file export',()=>assert.deepEqual(C.normalize(C.compact(s)),s));
test('playable adjustment requires both correct placements before success and retries a wrong first placement',()=>{
 const a=new Attempt(s);a.active=C.clone(s.adjustment.adjusted);a.lock();assert(!a.done);assert.equal(a.pendingPiece,'L');a.advance(2*1000/C.HZ);assert.equal(a.active.type,'L');assert.equal(a.active.y,0);a.active=C.clone(s.adjustment.next);a.lock();assert(a.done&&a.correct);
 const b=new Attempt(s);b.active=C.clone(s.adjustment.default);b.lock();assert(b.done&&!b.correct);assert(!b.pendingPiece);
});

test('after the adjusted ghost, the next ghost blinks beside its steady reference',()=>{const f=s.frames[4];assert.equal(s.frames[3].ghost.label,'Adjusted');assert.equal(f.ghost.label,'Next');assert.deepEqual(f.referenceGhost,{...s.adjustment.adjusted,label:'Adjusted'});assert.equal(f.active.y,0);assert(C.frameAt(f,0).ghost);assert.equal(C.frameAt(f,13).ghost,undefined);assert(C.frameAt(f,13).referenceGhost);});

test('S-Z Koryan mirrors the NES stack and uses Z then S around two motif corners',()=>{
 const raw=require('../situations/adjustment-sz-koryan.js'),s=C.normalize(raw),a=s.adjustment;
 const original=['SSSS......','SSSS....S.','SSSSS..SS.'];assert.deepEqual(C.compose(s.frames[0],18).slice(15).map(r=>r.map(c=>c==='.'?'.':'S').join('')),original.map(r=>[...r].reverse().join('')));
 assert.equal(a.adjusted.type,'Z');assert.equal(a.next.type,'S');assert.deepEqual(s.frames[0].motif.cells,[[2,17],[5,17]]);
 const board=C.compose(s.frames[0],18);assert(fits(board,a.default));assert(!fits(C.compose({board,active:a.default},18),a.next));assert(fits(board,a.adjusted));assert(fits(C.compose({board,active:a.adjusted},18),a.next));
 for(const f of s.frames.filter(f=>f.animate)){const stack=C.compose({...f,active:undefined},18);for(let t=0;t<=f.ticks;t++)assert(fits(stack,C.frameAt(f,t).active));}
 const clean=global.TetrisCourse.clean(s);for(const f of clean.frames)if(f.active)assert(fits(C.compose({...f,active:undefined},18),f.active));
 assert.deepEqual(C.normalize(C.compact(s)),s);
 const attempt=new Attempt(s);attempt.active=C.clone(a.adjusted);attempt.lock();assert(!attempt.done);attempt.advance(2*1000/C.HZ);assert.equal(attempt.active.type,'S');attempt.active=C.clone(a.next);attempt.lock();assert(attempt.done&&attempt.correct);
});

test('Hook mirrors the stack, turns L inward and keeps the wall open for I',()=>{
 const s=C.normalize(require('../situations/adjustment-hook.js')),a=s.adjustment,board=C.compose(s.frames[0],18);
 assert.deepEqual(board.slice(16).map(r=>r.map(c=>c==='.'?'.':'S').join('')),['.SSSSSSS..','.SSSSSSS..']);assert.equal(a.adjusted.type,'L');assert.equal(a.next.type,'I');assert.deepEqual(s.frames[0].motif.cells,[[7,16],[7,17]]);
 assert(fits(board,a.default));assert(!fits(C.compose({board,active:a.default},18),a.next));assert(fits(C.compose({board,active:a.adjusted},18),a.next));
 for(const f of s.frames.filter(f=>f.animate)){const stack=C.compose({...f,active:undefined},18);for(let t=0;t<=f.ticks;t++)assert(fits(stack,C.frameAt(f,t).active));}
 for(const f of global.TetrisCourse.clean(s).frames)if(f.active)assert(fits(C.compose({...f,active:undefined},18),f.active));
 assert.deepEqual(C.normalize(C.compact(s)),s);const attempt=new Attempt(s);attempt.active=C.clone(a.adjusted);attempt.lock();assert(!attempt.done);attempt.advance(2*1000/C.HZ);assert.equal(attempt.active.type,'I');attempt.active=C.clone(a.next);attempt.lock();assert(attempt.done&&attempt.correct);
});

test('both Pullbacks keep the full I descent clear, while their defaults obstruct it',()=>{
 for(const key of ['adjustment-pullback-l-richard','adjustment-pullback-l-tetris']){const s=C.normalize(require('../situations/'+key+'.js')),a=s.adjustment,base=C.compose(s.frames[0],18),adjusted=C.compose({board:base,active:a.adjusted},18),normal=C.compose({board:base,active:a.default},18);
  assert(fits(base,a.default));assert(fits(base,a.adjusted));assert(fits(adjusted,a.next));assert(Array.from({length:a.next.y+1},(_,y)=>({...a.next,y})).every(p=>fits(adjusted,p)));assert(Array.from({length:a.next.y+1},(_,y)=>({...a.next,y})).some(p=>!fits(normal,p)));
  const game=new Attempt(s);game.active=C.clone(a.adjusted);game.lock();assert(!game.done);game.advance(2*1000/C.HZ);game.active=C.clone(a.next);game.lock();assert(game.correct&&game.done);if(key.endsWith('tetris'))assert.equal(game.rows,4);assert.deepEqual(C.normalize(C.compact(s)),s);
 }
});
test('Blue Sponge supports Z and T as next-piece variants in one lesson',()=>{
 const base=C.normalize(require('../situations/adjustment-blue-sponge.js'));assert.deepEqual(base.adjustment.alternatives.map(a=>a.type),['Z','T']);
 for(const type of ['Z','T']){const s=C.normalize(global.TetrisCourse.variant(base,type)),a=s.adjustment,board=C.compose(s.frames[0],18);assert.equal(a.next.type,type);assert(!fits(C.compose({board,active:a.default},18),a.next));assert(fits(C.compose({board,active:a.adjusted},18),a.next));
  for(const f of s.frames.filter(f=>f.animate)){const b=C.compose({...f,active:undefined},18);for(let t=0;t<=f.ticks;t++)assert(fits(b,C.frameAt(f,t).active));}
  for(const f of global.TetrisCourse.clean(s).frames)if(f.active)assert(fits(C.compose({...f,active:undefined},18),f.active));assert.deepEqual(C.normalize(C.compact(s)),s);
 }
});
test('all three new lesson animations remain clear on their mirrored stacks',()=>{
 for(const key of ['adjustment-pullback-l-richard','adjustment-pullback-l-tetris','adjustment-blue-sponge']){const s=C.normalize(require('../situations/'+key+'.js'));for(const f of s.frames.filter(f=>f.animate)){const b=C.compose({...f,active:undefined},18);for(let t=0;t<=f.ticks;t++)assert(fits(b,C.frameAt(f,t).active));}for(const f of global.TetrisCourse.clean(s).frames)if(f.active)assert(fits(C.compose({...f,active:undefined},18),f.active));}
});

test('the tetris Pullback clears four rows before highlighting the lowered stack',()=>{
 const s=C.normalize(require('../situations/adjustment-pullback-l-tetris.js')),i=s.frames.findIndex(f=>f.clear);assert.equal(i,s.frames.findIndex(f=>f.active?.type==='I'&&f.animate)+1);const clear=s.frames[i];assert.deepEqual(clear.clearRows,[14,15,16,17]);assert.equal(clear.ticks,C.LINE_CLEAR.ticks);
 const after=s.frames[i+1],collapsed=C.clearAfterBoard(clear,18);assert.deepEqual(C.compose(after,18),collapsed);assert.equal(after.placementHighlights.length,1);assert.equal(after.placementHighlights[0].y,s.adjustment.adjusted.y+4);assert.deepEqual(s.frames.at(-1).motif.cells,s.frames[0].motif.cells.map(([x,y])=>[x,y+4]));assert.deepEqual(C.compose(s.frames.at(-1),18),collapsed);assert(!collapsed.flat().includes('I'));
 const clean=global.TetrisCourse.clean(s),at=clean.frames.findIndex(f=>f.clear);assert(at>=0);assert.deepEqual(C.compose(clean.frames[at+1],18),collapsed);assert.deepEqual(C.normalize(C.compact(s)),s);
});

test('Red Sponge, Oj and three-wide O adjustments mirror their source stacks and leave room for the next piece',()=>{
 const defs=[['adjustment-red-sponge',['SSS...SSS.','SSS..SSSS.','SSSSSSSSS.']],['adjustment-oj',['SSSSSS....','SSSSSS....','SSSSSSS...','SSSSSSSSS.']],['adjustment-o-three-wide',['...S......','...SSS....','...SSSSS..','SSSSSSSSS.']]];
 for(const[key,source]of defs){const original=C.normalize(require('../situations/'+key+'.js'));assert.deepEqual(C.compose(original.frames[0],18).slice(-source.length).map(r=>r.map(c=>c==='.'?'.':'S').join('')),source.map(r=>[...r].reverse().join('')));
  const options=original.adjustment.alternatives||[original.adjustment.next];for(const option of options){const s=C.normalize(global.TetrisCourse.variant(original,option.type)),a=s.adjustment,base=C.compose(s.frames[0],18);assert(fits(base,a.default));assert(fits(base,a.adjusted));assert.equal(fits(C.compose({board:base,active:a.default},18),a.next),!!option.adjusted);assert(fits(C.compose({board:base,active:a.adjusted},18),a.next));
   for(const f of s.frames.filter(f=>f.animate)){const board=C.compose({...f,active:undefined},18);for(let t=0;t<=f.ticks;t++)assert(fits(board,C.frameAt(f,t).active),s.title+' animation');}
   for(const f of global.TetrisCourse.clean(s).frames)if(f.active)assert(fits(C.compose({...f,active:undefined},18),f.active),s.title+' clean');
   assert.deepEqual(C.normalize(C.compact(s)),s);const attempt=new Attempt(s);attempt.active=C.clone(a.adjusted);attempt.lock();assert(!attempt.done);attempt.advance(2*1000/C.HZ);attempt.active=C.clone(a.next);attempt.lock();assert(attempt.done&&attempt.correct);
  }
 }
});

test('all adjustments show the current piece at spawn in the very first step',()=>{
 for(const s of C.demos().filter(s=>s.chapter==='Adjustments')){assert(s.frames[0].active,s.title);assert.equal(s.frames[0].active.type,s.adjustment.adjusted.type);assert.equal(s.frames[0].active.x,3);assert.equal(s.frames[0].active.y,C.spawn(s.frames[0].active.type).y);assert.equal(s.frames[0].active.rotation,0);assert(s.frames[0].motif);}
 assert.deepEqual(C.cells('O',0),[[1,1],[2,1],[1,2],[2,2]]);
});

 test('playback uses the ROM two-frame entry delay between adjustment pieces',()=>{
 assert.equal(C.ENTRY_DELAY,2);for(const s of C.demos().filter(s=>s.chapter==='Adjustments')){const spawn=s.frames.find(f=>f.active?.type===s.adjustment.next.type&&f.active.y===C.spawn(f.active.type).y&&!f.animate&&f.lessonStage===6);assert.equal(spawn.ticks,2,s.title);const clean=global.TetrisCourse.clean(s);if(!s.frames.some(f=>f.clear&&f.lessonStage===5)){const gap=clean.frames.findIndex(f=>!f.active&&!f.clear);assert(gap>0);assert.equal(clean.frames[gap].ticks,2);assert.equal(clean.frames[gap+1].active.type,s.adjustment.next.type);}assert.equal(clean.frames.at(-1).ticks,2);}
});

test("three-wide L forms a reverse r beside O with one mino above O",()=>{const base=C.normalize(require("../situations/adjustment-o-three-wide.js")),s=C.normalize(global.TetrisCourse.variant(base,"L"));assert.deepEqual(s.adjustment.adjusted,s.adjustment.default);assert.deepEqual(s.adjustment.next,{type:"L",x:8,y:14,rotation:1});assert.deepEqual(s.frames.find(f=>f.active?.type==="O"&&f.animate).active,s.adjustment.default);});

test('OL descends outside O and tucks right once beneath it',()=>{const s=C.normalize(require('../situations/adjustment-oj.js'));assert.equal(s.title,'OL adjustment (Ori: Oj)');const i=s.frames.findIndex(f=>f.step==='6b'),t=s.frames[i];assert.equal(t.active.x,s.frames[i-1].active.x+1);assert.equal(t.active.y,s.frames[i-1].active.y);assert.deepEqual(t.buttons,['Right']);assert.deepEqual(t.active,s.adjustment.next);for(let n=i-1;n<=i;n++)for(let tick=0;tick<=s.frames[n].ticks;tick++)assert(fits(C.compose({...s.frames[n],active:undefined},18),C.frameAt(s.frames[n],tick).active));const clean=global.TetrisCourse.clean(s);assert.equal(clean.frames.filter(f=>f.active?.type==='L'&&f.buttons.includes('Right')).length,1);for(const f of clean.frames)if(f.active)assert(fits(C.compose({...f,active:undefined},18),f.active));});

test('four new NES adjustments mirror their stacks and play both placements without collisions',()=>{const defs=[['adjustment-o-j-dependency',['S....SSSS.','S.SSSSSSS.','SSSSSSSSS.']],['adjustment-o-l-dependency',['SS....SSS.','SSS...SSS.','SSSSSSSSS.']],['adjustment-sz-shadow-t',['SS........','SSS.......','SSS.......','SSSS...SS.','SSSSS.SSS.']],['adjustment-kofi-lorange',['SSSSS.....','SSSSSSS...','SSSSSSSSS.']]];for(const[key,source]of defs){const s=C.normalize(require('../situations/'+key+'.js')),base=C.compose(s.frames[0],18),a=s.adjustment;assert.deepEqual(base.slice(-source.length).map(r=>r.map(c=>c==='.'?'.':'S').join('')),source.map(r=>[...r].reverse().join('')));assert(fits(base,a.default));assert(fits(base,a.adjusted));assert(fits(C.compose({board:base,active:a.adjusted},18),a.next));for(const f of s.frames.filter(f=>f.animate))for(let t=0;t<=f.ticks;t++)assert(fits(C.compose({...f,active:undefined},18),C.frameAt(f,t).active),key+' lesson path');for(const f of global.TetrisCourse.clean(s).frames)if(f.active)assert(fits(C.compose({...f,active:undefined},18),f.active),key+' clean path');const attempt=new Attempt(s);attempt.active=C.clone(a.adjusted);attempt.lock();attempt.advance(C.ENTRY_DELAY*1000/C.HZ);attempt.active=C.clone(a.next);attempt.lock();assert(attempt.done&&attempt.correct);assert.deepEqual(C.normalize(C.compact(s)),s);assert(C.demos().some(v=>v.title===s.title));}const k=C.normalize(require('../situations/adjustment-kofi-lorange.js'));assert.deepEqual(k.frames.find(f=>f.step==='6b').buttons,['Right']);});

