test('Double L, Pump Fake, Blank Thing and Saelee have mirrored stacks and safe two-piece paths',()=>{const defs=[['adjustment-koryan-double-l',['S.........','S.........','SSSS......','SSSS......','SSSS..SSS.','SSSSS.SSS.']],['adjustment-pump-fake',['SSS.......','SSS.......','SSS.SSSSS.','SSS.SSSSS.','SSSSSSSSS.','SSSSSSSSS.']],['adjustment-blank-thing',['SSSSSSS...','SSSSSSS...','SSSSSSS...','SSSSSSSSS.']],['adjustment-joseph-saelee',['.SS....SS.','SSS....SS.','SSSS.SSSS.','SSSSSSSSS.']]];for(const[key,source]of defs){const s=C.normalize(require('../situations/'+key+'.js')),a=s.adjustment,base=C.compose(s.frames[0],18);assert.deepEqual(base.slice(-source.length).map(r=>r.map(c=>c==='.'?'.':'S').join('')),source.map(r=>[...r].reverse().join('')));assert(fits(base,a.default));assert(fits(base,a.adjusted));assert(fits(C.compose({board:base,active:a.adjusted},18),a.next));for(const f of s.frames.filter(f=>f.animate))for(let t=0;t<=f.ticks;t++)assert(fits(C.compose({...f,active:undefined},18),C.frameAt(f,t).active),key+' lesson');for(const f of global.TetrisCourse.clean(s).frames)if(f.active)assert(fits(C.compose({...f,active:undefined},18),f.active),key+' clean');const attempt=new Attempt(s);attempt.active=C.clone(a.adjusted);attempt.lock();attempt.advance(C.ENTRY_DELAY*1000/C.HZ);attempt.active=C.clone(a.next);attempt.lock();assert(attempt.done&&attempt.correct);assert.deepEqual(C.normalize(C.compact(s)),s);assert(C.demos().some(v=>v.title===s.title));}const blank=C.normalize(require('../situations/adjustment-blank-thing.js'));assert.deepEqual(blank.frames.find(f=>f.step==='6b').buttons,['Right']);});

test('Luke, Jonas, vertical J/Z and both Water variants mirror their references and play safely',()=>{const defs=[['adjustment-luke-anderson',['SSSSS.....','SSSSSS....','SSSSSSS...','SSSSSSSSS.','SSSSSSSSS.']],['adjustment-jonas-neubauer',['SSSS......','SSSS...SS.','SSSSSSSSS.']],['adjustment-j-vert-z-vert',['...SSSSSS.','SSSSSSSSS.']],['adjustment-water-t-hooks',['SSS...SSS.','SSS...SSS.','SSS.S.SSS.']]];for(const[key,source]of defs){const original=C.normalize(require('../situations/'+key+'.js'));for(const option of original.adjustment.alternatives||[original.adjustment.next]){const s=C.normalize(global.TetrisCourse.variant(original,option.type)),a=s.adjustment,base=C.compose(s.frames[0],18);assert.deepEqual(base.slice(-source.length).map(r=>r.map(c=>c==='.'?'.':'S').join('')),source.map(r=>[...r].reverse().join('')));assert(fits(base,a.default));assert(fits(base,a.adjusted));assert(fits(C.compose({board:base,active:a.adjusted},18),a.next));for(const f of s.frames.filter(f=>f.animate))for(let t=0;t<=f.ticks;t++)assert(fits(C.compose({...f,active:undefined},18),C.frameAt(f,t).active),key+' lesson');for(const f of global.TetrisCourse.clean(s).frames)if(f.active)assert(fits(C.compose({...f,active:undefined},18),f.active),key+' clean');const attempt=new Attempt(s);attempt.active=C.clone(a.adjusted);attempt.lock();attempt.advance(C.ENTRY_DELAY*1000/C.HZ);attempt.active=C.clone(a.next);attempt.lock();assert(attempt.done&&attempt.correct);assert.deepEqual(C.normalize(C.compact(s)),s);assert(C.demos().some(v=>v.title===s.title));}}const original=C.normalize(require('../situations/adjustment-water-t-hooks.js')),alt=C.normalize(global.TetrisCourse.variant(original,'L'));assert.equal(alt.adjustment.adjusted.rotation,3);assert(alt.frames.some(f=>f.lessonStage===5&&f.buttons.includes('B')));assert.equal(alt.frames.find(f=>f.step==='4').ghost.label,'Adjusted');assert(!alt.frames.some(f=>f.caption.includes('Keep O')));});

test('VITS, Sisyphus, Spocket, 5 and beside, and Hanging Feet follow safe mirrored paths',()=>{const defs=[['adjustment-vits-palito',['SSS.......','SSSSSS....','SSSSSSS...','SSSSSSS...','SSSSSSSS..','SSSSSSSS..']],['adjustment-o-z-sisyphus',['.S........','SSS.......','SSS.......','SSS.......','SSSS......','SSSSSSSSS.']],['adjustment-spocket',['SSS.......','SSS.....S.','SSSS..SSS.']],['adjustment-five-beside',['SS........','SS...SSSS.','SS...SSSS.','SSSSSSSSS.','SSSSSSSSS.']],['adjustment-l-for-t-dangler',['SSSSS.....','SSSSS.....','SSSSSSS...','SSSSSSSS..','SSSSSSSSS.','SSSSSSSSS.']]];for(const[key,source]of defs){const s=C.normalize(require('../situations/'+key+'.js')),a=s.adjustment,base=C.compose(s.frames[0],18);assert.deepEqual(base.slice(-source.length).map(r=>r.map(c=>c==='.'?'.':'S').join('')),source.map(r=>[...r].reverse().join('')));assert(fits(base,a.default));assert(fits(base,a.adjusted));assert(fits(C.compose({board:base,active:a.adjusted},18),a.next));for(const f of s.frames.filter(f=>f.animate))for(let t=0;t<=f.ticks;t++)assert(fits(C.compose({...f,active:undefined},18),C.frameAt(f,t).active),key+' lesson');for(const f of global.TetrisCourse.clean(s).frames)if(f.active)assert(fits(C.compose({...f,active:undefined},18),f.active),key+' clean');const attempt=new Attempt(s);attempt.active=C.clone(a.adjusted);attempt.lock();attempt.advance(C.ENTRY_DELAY*1000/C.HZ);attempt.active=C.clone(a.next);attempt.lock();assert(attempt.done&&attempt.correct);assert.deepEqual(C.normalize(C.compact(s)),s);assert(C.demos().some(v=>v.title===s.title));}const vits=C.normalize(require('../situations/adjustment-vits-palito.js'));assert.deepEqual(vits.frames.findLast(f=>f.lessonStage===6&&f.animate).buttons,['Right']);assert.equal(global.TetrisCourse.clean(vits).frames.filter(f=>f.active?.type==='I'&&f.buttons.includes('Right')).slice(-1).length,1);const dangler=C.normalize(require('../situations/adjustment-l-for-t-dangler.js'));assert.deepEqual(dangler.frames.findLast(f=>f.lessonStage===6&&f.animate).buttons,['Right']);assert.equal(global.TetrisCourse.clean(dangler).frames.filter(f=>f.active?.type==='T'&&f.buttons.includes('Right')).length,1);});

test('Sisyphus keeps the supported Z-next arrangement',()=>{const scene=C.normalize(require('../situations/adjustment-o-z-sisyphus.js'));assert.equal(scene.adjustment.next.type,'Z');assert(!scene.adjustment.alternatives?.length);});

test('Thomas Jefferson, basic T-spin, ST Tuck and LeBron mirror the reference stacks and reach their goals',()=>{const defs=[['adjustment-thomas-jefferson-1',['SSSSSS....','SSSSSS....','SSSSSSSSS.','SSSSSSSSS.']],['adjustment-thomas-jefferson-2',['SSSSS.....','SSSSSS....','SSSSSSSSS.','SSSSSSSSS.']],['adjustment-basic-tspin',['SSS.SSSSS.','SSSSSSSSS.','SSSSSSSSS.']],['adjustment-st-tuck',['SSSSSS....','SSSSSSSS..','SSSSSSSSS.','SSSSSSSSS.']],['adjustment-t-flip-lebron',['SSS.......','SSS.......','SSSS...SS.','SSSSS.SSS.','SSSSSSSSS.']]];for(const[key,source]of defs){const original=C.normalize(require('../situations/'+key+'.js'));for(const option of original.adjustment.alternatives||[original.adjustment.next]){const s=C.normalize(global.TetrisCourse.variant(original,option.type)),a=s.adjustment,base=C.compose(s.frames[0],18);assert.deepEqual(base.slice(-source.length).map(r=>r.map(c=>c==='.'?'.':'S').join('')),source.map(r=>[...r].reverse().join('')));assert(fits(base,a.default));assert(fits(base,a.adjusted));assert(fits(C.compose({board:base,active:a.adjusted},18),a.next));for(const f of s.frames.filter(f=>f.animate))for(let t=0;t<=f.ticks;t++)assert(fits(C.compose({...f,active:undefined},18),C.frameAt(f,t).active),key+' lesson');for(const f of global.TetrisCourse.clean(s).frames)if(f.active)assert(fits(C.compose({...f,active:undefined},18),f.active),key+' clean');const attempt=new Attempt(s);attempt.active=C.clone(a.adjusted);attempt.lock();attempt.advance(C.ENTRY_DELAY*1000/C.HZ);attempt.active=C.clone(a.next);attempt.lock();assert(attempt.done&&attempt.correct);assert.deepEqual(C.normalize(C.compact(s)),s);assert(C.demos().some(v=>v.title===s.title));}}const tuck=C.normalize(require('../situations/adjustment-st-tuck.js'));assert.deepEqual(tuck.frames.find(f=>f.step==='6b').buttons,['Right']);assert.equal(global.TetrisCourse.clean(tuck).frames.filter(f=>f.active?.type==='T'&&f.buttons.includes('Right')).length,1);const lebron=C.normalize(require('../situations/adjustment-t-flip-lebron.js')),alt=C.normalize(global.TetrisCourse.variant(lebron,'S'));assert.equal(alt.adjustment.adjusted.rotation,3);assert.deepEqual(alt.frames.find(f=>f.step==='5').buttons,['B']);assert.notDeepEqual(alt.frames[0].motif.cells,lebron.frames[0].motif.cells);});

test('First ever, unnamed S/J, key tuck setup and 3 piece have safe mirrored placement sequences',()=>{const defs=[['adjustment-first-ever',['SSSSS.....','SSSSSSS...','SSSSSSSSS.','SSSSSSSSS.']],['adjustment-unnamed-s-j',['S....SS...','S....SSS..','SS..SSSSS.','SS.SSSSSS.','SSSSSSSSS.','SSSSSSSSS.']],['adjustment-key-tuck-setup',['SSSS......','SSSS.S....','SSSSSSSS..','SSSSSSSSS.','SSSSSSSSS.']],['adjustment-three-piece',['SS........','SSSSSSS...','SSSSSS....','SSSSSSSS..','SSSSSSSSS.']]];for(const[key,source]of defs){const s=C.normalize(require('../situations/'+key+'.js')),a=s.adjustment,base=C.compose(s.frames[0],18);assert.deepEqual(base.slice(-source.length).map(r=>r.map(c=>c==='.'?'.':'S').join('')),source.map(r=>[...r].reverse().join('')));assert(fits(base,a.default));assert(fits(base,a.adjusted));assert(fits(C.compose({board:base,active:a.adjusted},18),a.next));for(const f of s.frames.filter(f=>f.animate))for(let t=0;t<=f.ticks;t++)assert(fits(C.compose({...f,active:undefined},18),C.frameAt(f,t).active),key+' lesson');for(const f of global.TetrisCourse.clean(s).frames)if(f.active)assert(fits(C.compose({...f,active:undefined},18),f.active),key+' clean');const attempt=new Attempt(s);attempt.active=C.clone(a.adjusted);attempt.lock();attempt.advance(C.ENTRY_DELAY*1000/C.HZ);attempt.active=C.clone(a.next);attempt.lock();assert(attempt.done&&attempt.correct);assert.deepEqual(C.normalize(C.compact(s)),s);assert(C.demos().some(v=>v.title===s.title));}const s=C.normalize(require('../situations/adjustment-three-piece.js'));assert.deepEqual(s.frames.find(f=>f.step==='5b').buttons,['Right']);assert.equal(global.TetrisCourse.clean(s).frames.filter(f=>f.active?.type==='L'&&f.buttons.includes('Right')).length,1);});

test('3 piece leaves four Tetris-ready rows and preserves the wall well',()=>{const s=C.normalize(require('../situations/adjustment-three-piece.js'));assert.deepEqual(s.adjustment.next,{type:'I',x:0,y:13,rotation:1});const f=s.frames.find(f=>f.placementHighlights),board=C.compose(f,18);assert.deepEqual(C.fullRows(board),[]);for(const row of board.slice(-4)){assert.equal(row[0],'.');assert(row.slice(1).every(c=>c!=='.'));}});

test('JO and Below, Jigsaw, High Rise, Gun and square-hole preservation have safe mirrored sequences',()=>{const defs=[['adjustment-jo-and-below',['SSSSS.S...','SSSSSSS...','SSSSSSSSS.','SSSSSSSSS.']],['adjustment-jigsaw',['SSSS......','SSSSSSS...','SSSSSSSSS.']],['adjustment-i-for-j-high-rise',['SSS.......','SSS.......','SSSS.SS...','SSSSSSS...','SSSSSSSS..','SSSSSSSSS.']],['adjustment-gun',['SSSSSS....','SSSSSSSS..','SSSSSSSS..']],['adjustment-preserving-square-hole',['SS..SSSS..','SS..SSSSS.','SSSSSSSSS.']]];for(const[key,source]of defs){const raw=require('../situations/'+key+'.js'),s=C.normalize(raw),a=s.adjustment,base=C.compose(s.frames[0],18);assert.deepEqual(base.slice(-source.length).map(r=>r.map(c=>c==='.'?'.':'S').join('')),source.map(r=>[...r].reverse().join('')));assert(fits(base,a.default));assert(fits(base,a.adjusted));assert(fits(C.compose({board:base,active:a.adjusted},18),a.next));for(const f of s.frames.filter(f=>f.animate))for(let t=0;t<=f.ticks;t++)assert(fits(C.compose({...f,active:undefined},18),C.frameAt(f,t).active),key+' lesson');for(const f of global.TetrisCourse.clean(s).frames)if(f.active)assert(fits(C.compose({...f,active:undefined},18),f.active),key+' clean');const attempt=new Attempt(s);attempt.active=C.clone(a.adjusted);attempt.lock();attempt.advance(C.ENTRY_DELAY*1000/C.HZ);attempt.active=C.clone(a.next);attempt.lock();assert(attempt.done&&attempt.correct);assert.deepEqual(C.normalize(C.compact(s)),s);assert(C.demos().some(v=>v.title===s.title));assert(raw.frames.filter(f=>f.rows).every(f=>Object.keys(f.rows).length<6));}for(const key of ['adjustment-jo-and-below','adjustment-jigsaw','adjustment-gun']){const s=C.normalize(require('../situations/'+key+'.js'));assert.deepEqual(s.frames.find(f=>f.step==='6b').buttons,['Right']);assert.equal(global.TetrisCourse.clean(s).frames.filter(f=>f.active?.type===s.adjustment.next.type&&f.buttons.includes('Right')).length,1);}const jo=C.normalize(require('../situations/adjustment-jo-and-below.js')),board=C.compose(jo.frames.find(f=>f.placementHighlights),18);for(const row of board.slice(-4)){assert.equal(row[0],'.');assert(row.slice(1).every(c=>c!=='.'));}});

test('Double Z, Tournament Organizer, High Chair, JD and Boiler keep mirrored stacks and valid input sequences',()=>{const defs=[['adjustment-double-z-start',['SSSSSSSSS.','SSSSSSSSS.']],['adjustment-tournament-organizer',['SSSSSS....','SSSSSS....','SSSSSS....','SSSSSSS...']],['adjustment-high-chair',['S.........','S.........','SS........','SS........','SSS..SSSS.']],['adjustment-jd-spin',['SSSSSS....','SSSSS.....','SSSSSS.SS.','SSSSSSSSS.']],['adjustment-boiler-spin',['SSSSSS....','SSSSS.....','SSSSSS.SS.','SSSSSSSSS.']]];for(const[key,source]of defs){const s=C.normalize(require('../situations/'+key+'.js')),a=s.adjustment,base=C.compose(s.frames[0],18);assert.deepEqual(base.slice(-source.length).map(r=>r.map(c=>c==='.'?'.':'S').join('')),source.map(r=>[...r].reverse().join('')));assert(fits(base,a.default));assert(fits(base,a.adjusted));assert(fits(C.compose({board:base,active:a.adjusted},18),a.next));for(const f of s.frames.filter(f=>f.animate))for(let t=0;t<=f.ticks;t++)assert(fits(C.compose({...f,active:undefined},18),C.frameAt(f,t).active),key+' lesson');const clean=global.TetrisCourse.clean(s);for(const f of clean.frames)if(f.active)assert(fits(C.compose({...f,active:undefined},18),f.active),key+' clean');assert.deepEqual(clean.frames.findLast(f=>f.active).active,a.next);const attempt=new Attempt(s);attempt.active=C.clone(a.adjusted);attempt.lock();attempt.advance(C.ENTRY_DELAY*1000/C.HZ);attempt.active=C.clone(a.next);attempt.lock();assert(attempt.done&&attempt.correct);assert.deepEqual(C.normalize(C.compact(s)),s);assert(C.demos().some(v=>v.title===s.title));}for(const key of ['adjustment-jd-spin','adjustment-boiler-spin']){const s=C.normalize(require('../situations/'+key+'.js')),clean=global.TetrisCourse.clean(s),first=clean.frames.filter(f=>f.active?.type==='T');assert.deepEqual(first.at(-1).active,s.adjustment.adjusted);assert.equal(first.filter(f=>f.buttons.includes('Right')).length,1);assert.deepEqual(first.findLast(f=>f.buttons.includes('A')||f.buttons.includes('B')).buttons,['A']);const board=C.compose(s.frames.find(f=>f.placementHighlights),18);for(const row of board.slice(-4)){assert.equal(row[0],'.');assert(row.slice(1).every(c=>c!=='.'));}}const high=C.normalize(require('../situations/adjustment-high-chair.js'));assert.deepEqual(high.frames.find(f=>f.step==='6b').buttonOptions,['B','A']);});

test('JD and Boiler execute their authored final inputs, and either High Chair button works',()=>{for(const[key,start,inputs]of [['adjustment-jd-spin',{type:'T',x:1,y:14,rotation:2},['right','a']],['adjustment-boiler-spin',{type:'T',x:1,y:13,rotation:3},['b','down','right','a']]]){const s=C.normalize(require('../situations/'+key+'.js')),attempt=new Attempt(s);attempt.active=start;assert(attempt.fits(start));for(const input of inputs)assert(attempt.input(input),key+' '+input);assert.deepEqual(attempt.active,s.adjustment.adjusted);attempt.lock();assert(attempt.correct);}const high=C.normalize(require('../situations/adjustment-high-chair.js'));for(const button of ['a','b']){const attempt=new Attempt(high);attempt.active=C.clone(high.adjustment.adjusted);attempt.lock();attempt.advance(C.ENTRY_DELAY*1000/C.HZ);attempt.active={type:'S',x:5,y:15,rotation:1};assert(attempt.input(button));attempt.lock();assert(attempt.done&&attempt.correct);}const z=C.normalize(require('../situations/adjustment-double-z-start.js')),clean=global.TetrisCourse.clean(z),gap=clean.frames.findIndex(f=>!f.active);assert.equal(clean.frames.slice(0,gap).filter(f=>f.buttons.includes('Right')).length,2);const base=z.frames[0].board,forward=C.compose({board:C.compose({board:base,active:z.adjustment.adjusted},18),active:z.adjustment.next},18),reverse=C.compose({board:C.compose({board:base,active:z.adjustment.next},18),active:z.adjustment.adjusted},18);assert.deepEqual(forward,reverse);});

test('Nenu, Twister, Sled, Boomerang and Street mirror the references and settle on real landings',()=>{const defs=[['adjustment-nenu',['S.........','SSSS......','SSSSS.SSS.','SSSSSSSSS.']],['adjustment-twister',['S.........','SS......S.','SSSS...SS.','SSSSS.SSS.','SSSSSSSSS.','SSSSSSSSS.']],['adjustment-sled',['.....SSSS.','...SSSSSS.','.SSSSSSSS.','SSSSSSSSS.']],['adjustment-boomerang',['....SSSSS.','...SSSSSS.']],['adjustment-street',['SSSSS.....','SSSSSSSS..']]];const grounded=(b,a)=>C.cells(a.type,a.rotation).some(([x,y])=>a.y+y+1>=18||b[a.y+y+1][a.x+x]!=='.');for(const[key,source]of defs){const raw=require('../situations/'+key+'.js'),s=C.normalize(raw),a=s.adjustment,base=C.compose(s.frames[0],18),locked=C.compose({board:base,active:a.adjusted},18);assert.deepEqual(base.slice(-source.length).map(r=>r.map(c=>c==='.'?'.':'S').join('')),source.map(r=>[...r].reverse().join('')));assert(fits(base,a.default));assert(fits(base,a.adjusted));assert(fits(locked,a.next));assert(grounded(base,a.default),key+' default floats');assert(grounded(base,a.adjusted),key+' first floats');assert(grounded(locked,a.next),key+' next floats');for(const f of s.frames.filter(f=>f.animate))for(let t=0;t<=f.ticks;t++)assert(fits(C.compose({...f,active:undefined},18),C.frameAt(f,t).active),key+' lesson');const clean=global.TetrisCourse.clean(s);for(const f of clean.frames)if(f.active)assert(fits(C.compose({...f,active:undefined},18),f.active),key+' clean');assert.deepEqual(clean.frames.findLast(f=>f.active).active,a.next);const attempt=new Attempt(s);attempt.active=C.clone(a.adjusted);attempt.lock();attempt.advance(C.ENTRY_DELAY*1000/C.HZ);attempt.active=C.clone(a.next);attempt.lock();assert(attempt.done&&attempt.correct);assert.deepEqual(C.normalize(C.compact(s)),s);assert(C.demos().some(v=>v.title===s.title));assert(raw.frames.filter(f=>f.rows).every(f=>Object.keys(f.rows).length<6));}const street=C.normalize(require('../situations/adjustment-street.js'));assert.deepEqual(street.frames.find(f=>f.step==='6b').buttons,['Right']);assert.equal(global.TetrisCourse.clean(street).frames.filter(f=>f.active?.type==='T'&&f.buttons.includes('Right')).length,1);const attempt=new Attempt(street);attempt.active=C.clone(street.adjustment.adjusted);attempt.lock();attempt.advance(C.ENTRY_DELAY*1000/C.HZ);attempt.active={...street.adjustment.next,x:-1};assert(attempt.input('right'));assert.deepEqual(attempt.active,street.adjustment.next);attempt.lock();assert(attempt.done&&attempt.correct);});

test('the new pullback supports both Z and T, and Noro burns one row then two',()=>{const base=C.normalize(require('../situations/adjustment-l-pullback-zt.js'));for(const type of ['Z','T']){const s=C.normalize(global.TetrisCourse.variant(base,type)),a=s.adjustment;assert(fits(C.compose({board:s.frames[0].board,active:a.adjusted},18),a.next));for(const f of s.frames.filter(f=>f.animate))for(let t=0;t<=f.ticks;t++)assert(fits(C.compose({...f,active:undefined},18),C.frameAt(f,t).active));for(const f of global.TetrisCourse.clean(s).frames)if(f.active)assert(fits(C.compose({...f,active:undefined},18),f.active));assert.deepEqual(C.normalize(C.compact(s)),s);}const n=C.normalize(require('../situations/adjustment-noro-pc-burn.js')),clears=n.frames.filter(f=>f.clear);assert.deepEqual(clears.map(f=>f.clearRows),[[13],[13,14]]);const clean=global.TetrisCourse.clean(n);assert.equal(clean.frames.filter(f=>f.clear).length,2);for(const f of n.frames.filter(f=>f.animate))for(let t=0;t<=f.ticks;t++)assert(fits(C.compose({...f,active:undefined},18),C.frameAt(f,t).active));for(const f of clean.frames)if(f.active)assert(fits(C.compose({...f,active:undefined},18),f.active));assert.deepEqual(C.compose(clean.frames.at(-1),18),C.clearAfterBoard(clears[1],18));const attempt=new Attempt(n);attempt.active=C.clone(n.adjustment.adjusted);attempt.lock();assert.equal(attempt.rows,1);attempt.advance(2*1000/C.HZ);assert.equal(attempt.active,null);attempt.advance((C.LINE_CLEAR.ticks-2)*1000/C.HZ);assert(attempt.active);assert(attempt.fits(n.adjustment.next));attempt.active=C.clone(n.adjustment.next);attempt.lock();assert(attempt.done&&attempt.correct);assert.equal(attempt.rows,2);assert.equal(attempt.totalRows,3);assert.deepEqual(C.normalize(C.compact(n)),n);});

test('Key tuck setup finishes with one right tuck of L underneath J',()=>{const s=C.normalize(require('../situations/adjustment-key-tuck-setup.js')),a=s.adjustment,board=C.compose({board:C.compose(s.frames[0],18),active:a.adjusted},18),pre=s.frames.find(f=>f.step==='6a').active;assert.equal(pre.x+1,a.next.x);assert(!fits(board,{...a.next,y:a.next.y-1}));assert(fits(board,pre));assert(fits(board,a.next));assert.deepEqual(s.frames.find(f=>f.step==='6b').buttons,['Right']);const clean=global.TetrisCourse.clean(s),l=clean.frames.filter(f=>f.active?.type==='L');assert.deepEqual(l.at(-1).active,a.next);assert.deepEqual(l.at(-6).buttons,['Right']);const attempt=new Attempt(s);attempt.active=C.clone(a.adjusted);attempt.lock();attempt.advance(C.ENTRY_DELAY*1000/C.HZ);attempt.active=C.clone(pre);assert(attempt.input('right'));assert.deepEqual(attempt.active,a.next);attempt.lock();assert(attempt.correct&&attempt.done);});

test('Good but Situational adjustments mirror the source, land both pieces and preserve their section',()=>{const defs=[['adjustment-vert-s-for-l',['SSSSS.....','SSSSSS....','SSSSSSSSS.','SSSSSSSSS.','SSSSSSSSS.']],['adjustment-zvert',['SSSSSSS...','SSSSSSS...','SSSSSSS...','SSSSSSSSS.','SSSSSSSSS.']],['adjustment-o-sz-flat',['S....SSSS.','SSSSSSSSS.']],['adjustment-js-tristop',['SSSSS.....','SSSSS.....','SSSSSSS...','SSSSSSSSS.','SSSSSSSSS.']]];for(const [key,source]of defs){const s=C.normalize(require('../situations/'+key+'.js')),a=s.adjustment,b=C.compose(s.frames[0],18),locked=C.compose({board:b,active:a.adjusted},18);assert.equal(s.section,'Good but Situational');assert.deepEqual(b.slice(-source.length).map(r=>r.map(c=>c==='.'?'.':'S').join('')),source.map(r=>[...r].reverse().join('')));for(const [board,pose]of [[b,a.default],[b,a.adjusted],[locked,a.next]]){assert(fits(board,pose),key+' landing');assert(!fits(board,{...pose,y:pose.y+1}),key+' grounded');}for(const f of s.frames.filter(f=>f.animate))for(let t=0;t<=f.ticks;t++)assert(fits(C.compose({...f,active:undefined},18),C.frameAt(f,t).active),key+' lesson');const clean=global.TetrisCourse.clean(s);for(const f of clean.frames)if(f.active)assert(fits(C.compose({...f,active:undefined},18),f.active),key+' clean');assert.deepEqual(clean.frames.findLast(f=>f.active).active,a.next);assert.deepEqual(C.normalize(C.compact(s)),s);const attempt=new Attempt(s);attempt.active=C.clone(a.adjusted);attempt.lock();attempt.advance(C.ENTRY_DELAY*1000/C.HZ);attempt.active=C.clone(a.next);attempt.lock();assert(attempt.correct&&attempt.done);}});
test('Tristop finishes with an actual S spin followed by one right tuck',()=>{const s=C.normalize(require('../situations/adjustment-js-tristop.js')),a=s.adjustment,attempt=new Attempt(s);attempt.active=C.clone(a.adjusted);attempt.lock();attempt.advance(C.ENTRY_DELAY*1000/C.HZ);attempt.active=C.clone(s.frames.find(f=>f.step==='6a').active);assert(attempt.input('b'));assert(attempt.input('right'));assert.deepEqual({...attempt.active,rotation:attempt.active.rotation%2},a.next);attempt.lock();assert(attempt.correct&&attempt.done);const clean=global.TetrisCourse.clean(s),frames=clean.frames.filter(f=>f.active?.type==='S');assert.equal(frames.filter(f=>f.buttons.includes('Right')).length,1);assert.deepEqual(frames.filter(f=>f.buttons.length).at(-1).buttons,['Right']);assert.equal(s.frames.find(f=>f.step==='6b').active.rotation,0);assert.equal(s.frames.find(f=>f.step==='6a').active.rotation,1);});

test('Secondary Tristop, Center Stack spin and L Spuck end with real inputs on mirrored stacks',()=>{const defs=[["adjustment-zt-tristop","ZT Tristop thing: secondary (Ori: ST Tristop thing)",["SSSSS.....","SSSSSS....","SSSSSSSSS.","SSSSSSSSS.","SSSSSSSSS."],{"type":"Z","x":1,"y":12,"rotation":1},{"type":"Z","x":2,"y":11,"rotation":0},{"type":"T","x":1,"y":13,"rotation":2},{"type":"T","x":0,"y":12,"rotation":1},[{"type":"T","x":0,"y":12,"rotation":2},{"type":"T","x":0,"y":13,"rotation":2},{"type":"T","x":1,"y":13,"rotation":2}],["A",null,"Right"]],["adjustment-center-stack-s-spin","Center Stack S spin (Ori: Center Stack Z spins)",[".......S..","......SS..","S.....SS..","SS....SS..","SSSS..S...","SSSSSSSS..","SSSSSSSS..","SSSSSSSSS."],{"type":"T","x":6,"y":11,"rotation":1},{"type":"T","x":6,"y":11,"rotation":0},{"type":"S","x":4,"y":12,"rotation":0},{"type":"S","x":4,"y":12,"rotation":1},[{"type":"S","x":4,"y":12,"rotation":0}],["B"]],["adjustment-l-spuck","L Spuck (Ori: J Spuck)",["S.........","SSSSS.....","SSSSS.....","SSSSSSSS..","SSSSSSSSS.","SSSSSSSSS."],{"type":"J","x":3,"y":12,"rotation":3},{"type":"J","x":2,"y":12,"rotation":0},{"type":"L","x":1,"y":13,"rotation":0},{"type":"L","x":0,"y":13,"rotation":1},[{"type":"L","x":0,"y":13,"rotation":0},{"type":"L","x":1,"y":13,"rotation":0}],["B","Right"]]];for(const [key,title,source,def,adj,next,pre,actions,inputs]of defs){const s=C.normalize(require('../situations/'+key+'.js')),a=s.adjustment,b=C.compose(s.frames[0],18),locked=C.compose({board:b,active:a.adjusted},18);assert.equal(s.section,'Good but Situational');assert.deepEqual(b.slice(-source.length).map(row=>row.map(c=>c==='.'?'.':'S').join('')),source.map(row=>[...row].reverse().join('')));for(const [board,pose]of [[b,a.default],[b,a.adjusted],[locked,a.next]]){assert(fits(board,pose),key+' landing');assert(!fits(board,{...pose,y:pose.y+1}),key+' grounded');}for(const f of s.frames.filter(f=>f.animate))for(let t=0;t<=f.ticks;t++)assert(fits(C.compose({...f,active:undefined},18),C.frameAt(f,t).active),key+' lesson path');const clean=global.TetrisCourse.clean(s);for(const f of clean.frames)if(f.active)assert(fits(C.compose({...f,active:undefined},18),f.active),key+' clean path');assert.deepEqual(clean.frames.findLast(f=>f.active).active,a.next);assert.deepEqual(C.normalize(C.compact(s)),s);const attempt=new Attempt(s);attempt.active=C.clone(a.adjusted);attempt.lock();attempt.advance(C.ENTRY_DELAY*1000/C.HZ);attempt.active=C.clone(pre);for(let i=0;i<actions.length;i++){const input=inputs[i]?inputs[i].toLowerCase():'down';assert(attempt.input(input),key+' final '+input);assert.deepEqual({...attempt.active,rotation:attempt.active.rotation%((next.type==='S'||next.type==='Z')?2:4)},actions[i]);}attempt.lock();assert(attempt.correct&&attempt.done,key+' practice goal');}});

test('Sodium Significant Other, Stepback, SO tuck and 234 have mirrored stacks and grounded collision-free landings',()=>{const defs=[["adjustment-significant-other","Significant Other: Sodium thing",[".S........","SSS.......","SSSSS.....","SSSSSSSSS."],{"type":"Z","x":6,"y":13,"rotation":1},{"type":"Z","x":4,"y":13,"rotation":0},{"type":"O","x":5,"y":12,"rotation":0},"Lay Z flat to create a square landing where there was none."],["adjustment-l-tap-over-o","L tap over for O: Stepback (Ori: J tap over for O)",["SSSSSS....","SSSSSSSS..","SSSSSSSSS."],{"type":"L","x":7,"y":13,"rotation":2},{"type":"L","x":5,"y":13,"rotation":2},{"type":"O","x":7,"y":12,"rotation":0},"Move L inward to leave a landing for O at the wall."],["adjustment-so-tuck","SO tuck: Zuke Anderson (Ori: ZO tuck)",["SSSSSS....","SSSSSSS...","SSSSSSS...","SSSSSSSSS.","SSSSSSSSS."],{"type":"S","x":0,"y":13,"rotation":1},{"type":"S","x":2,"y":11,"rotation":0},{"type":"O","x":0,"y":13,"rotation":0},"Lay S above the pocket, then tuck O right beneath it."],["adjustment-234","234",["SSSSS.....","SSSSS.....","SSSSS.S...","SSSSSSSSS.","SSSSSSSSS."],{"type":"S","x":3,"y":13,"rotation":1},{"type":"S","x":1,"y":13,"rotation":0},{"type":"L","x":3,"y":13,"rotation":1},"Move S across the pocket to leave a vertical landing for the next L."]];for(const [key,title,source]of defs){const s=C.normalize(require('../situations/'+key+'.js')),a=s.adjustment,b=C.compose(s.frames[0],18),locked=C.compose({board:b,active:a.adjusted},18);assert.equal(s.section,'Good but Situational');assert.deepEqual(b.slice(-source.length).map(row=>row.map(c=>c==='.'?'.':'S').join('')),source.map(row=>[...row].reverse().join('')));for(const [board,pose]of [[b,a.default],[b,a.adjusted],[locked,a.next]]){assert(fits(board,pose),key+' landing');assert(!fits(board,{...pose,y:pose.y+1}),key+' grounded');}for(const f of s.frames.filter(f=>f.animate))for(let t=0;t<=f.ticks;t++)assert(fits(C.compose({...f,active:undefined},18),C.frameAt(f,t).active),key+' lesson');const clean=global.TetrisCourse.clean(s);for(const f of clean.frames)if(f.active)assert(fits(C.compose({...f,active:undefined},18),f.active),key+' clean');assert.deepEqual(clean.frames.findLast(f=>f.active).active,a.next);assert.deepEqual(C.normalize(C.compact(s)),s);const attempt=new Attempt(s);attempt.active=C.clone(a.adjusted);attempt.lock();attempt.advance(C.ENTRY_DELAY*1000/C.HZ);if(key==='adjustment-so-tuck'){attempt.active=C.clone(s.frames.findLast(f=>f.lessonStage===6&&f.animate).animationFrom);assert(attempt.input('right'));assert.deepEqual(attempt.active,a.next);assert.equal(clean.frames.filter(f=>f.active?.type==='O'&&f.buttons.includes('Right')).length,1);}else attempt.active=C.clone(a.next);attempt.lock();assert(attempt.correct&&attempt.done);}});

test('Zip, reverse Tristop, ZO Opener and Eli Markstrom have mirrored stacks and grounded collision-free landings',()=>{const defs=[["adjustment-s-l-dependency-zip","S for L dependency: Zip (Ori: Z for J dependency)",["........S.",".......SS.",".....SSSS.","..SSSSSSS.","SSSSSSSSS."],{"type":"S","x":7,"y":13,"rotation":0},{"type":"S","x":7,"y":14,"rotation":1},{"type":"L","x":8,"y":14,"rotation":1},"Stand S in the low pocket to create a landing for L."],["adjustment-st-reverse-tristop","ST reverse Tristop: Nenu thing (Ori: ZT reverse Tristop)",["S.........","SS........","SSS.....S.","SSS....SS.","SSSSSSSSS.","SSSSSSSSS."],{"type":"S","x":1,"y":12,"rotation":1},{"type":"S","x":2,"y":12,"rotation":0},{"type":"T","x":3,"y":14,"rotation":2},"Lay S over the pocket, then spin T and tuck it left underneath."],["adjustment-z-flat-o-opener","Z flat for O: ZO Opener (Ori: S flat for O)",["SSSSSSSSS.","SSSSSSSSS."],{"type":"Z","x":7,"y":13,"rotation":0},{"type":"Z","x":5,"y":13,"rotation":0},{"type":"O","x":7,"y":13,"rotation":0},"Move Z inward and lay it flat, leaving the wall landing for O."],["adjustment-eli-markstrom-t","Eli Markstrom T: GarbageEgg T",["S.........","SSS.......","SSSS......","SSSSS.....","SSSSSS....","SSSSSSSS..","SSSSSSSSS.","SSSSSSSSS.","SSSSSSSSS."],{"type":"T","x":0,"y":12,"rotation":0},{"type":"T","x":0,"y":12,"rotation":1},{"type":"O","x":1,"y":11,"rotation":0},"Stand T at the wall to leave room for O and prepare the stack for a Tetris."]];for(const [key,title,source]of defs){const s=C.normalize(require('../situations/'+key+'.js')),a=s.adjustment,b=C.compose(s.frames[0],18),locked=C.compose({board:b,active:a.adjusted},18);assert.equal(s.section,'Good but Situational');assert.deepEqual(b.slice(-source.length).map(row=>row.map(c=>c==='.'?'.':'S').join('')),source.map(row=>[...row].reverse().join('')));for(const [board,pose]of [[b,a.default],[b,a.adjusted],[locked,a.next]]){assert(fits(board,pose),key+' landing');assert(!fits(board,{...pose,y:pose.y+1}),key+' grounded');}for(const f of s.frames.filter(f=>f.animate))for(let t=0;t<=f.ticks;t++)assert(fits(C.compose({...f,active:undefined},18),C.frameAt(f,t).active),key+' lesson');const clean=global.TetrisCourse.clean(s);for(const f of clean.frames)if(f.active)assert(fits(C.compose({...f,active:undefined},18),f.active),key+' clean');assert.deepEqual(clean.frames.findLast(f=>f.active).active,a.next);assert.deepEqual(C.normalize(C.compact(s)),s);const attempt=new Attempt(s);attempt.active=C.clone(a.adjusted);attempt.lock();attempt.advance(C.ENTRY_DELAY*1000/C.HZ);if(key==='adjustment-st-reverse-tristop'){attempt.active=C.clone(s.frames.find(f=>f.step==='6a').active);assert(attempt.input('b'));assert(attempt.input('down'));assert(attempt.input('left'));assert.deepEqual(attempt.active,a.next);assert.equal(clean.frames.filter(f=>f.active?.type==='T'&&f.buttons.includes('Left')).length,1);}else attempt.active=C.clone(a.next);attempt.lock();assert(attempt.correct&&attempt.done);}});

test('Nice 1.0, Vischer, Situp and Jarbage Egg mirror the source with grounded safe two-piece paths',()=>{const defs=[["adjustment-nice-10","Nice adjustment 1.0",[".S........","SSSS.S....","SSSSSS....","SSSSSS....","SSSSSSS...","SSSSSSS...","SSSSSSSSS.","SSSSSSSSS."],{"type":"J","x":0,"y":13,"rotation":0},{"type":"J","x":2,"y":11,"rotation":1},{"type":"O","x":-1,"y":13,"rotation":0},"Stand J beside the shelf to leave the wall landing for O."],["adjustment-vischer","Vischer Thing",["SSSSS....S","SSSSSS..SS","SSSSSS..S.","SSSSSSSSS."],{"type":"Z","x":2,"y":12,"rotation":0},{"type":"Z","x":3,"y":13,"rotation":1},{"type":"S","x":1,"y":13,"rotation":1},"Stand Z in the pocket and place S vertically beside it."],["adjustment-j-upright-z","J upright for Z: Situp (Ori: L upright for S)",["SSSS......","SSSS......","SSSSS...S.","SSSSSSSSS.","SSSSSSSSS."],{"type":"J","x":2,"y":13,"rotation":0},{"type":"J","x":2,"y":13,"rotation":1},{"type":"Z","x":4,"y":13,"rotation":1},"Stand J upright to leave a vertical landing for the next Z."],["adjustment-jarbage-egg","Jarbage Egg",["S.S.S.....","SSSSSS....","SSSSSS....","SSSSSSSS.."],{"type":"L","x":1,"y":15,"rotation":0},{"type":"L","x":0,"y":15,"rotation":1},{"type":"O","x":1,"y":14,"rotation":0},"Stand L at the wall to preserve the square landing beside it for O."]];for(const [key,title,source]of defs){const s=C.normalize(require('../situations/'+key+'.js')),a=s.adjustment,b=C.compose(s.frames[0],18),locked=C.compose({board:b,active:a.adjusted},18);assert.equal(s.section,'Good but Situational');assert.deepEqual(b.slice(-source.length).map(row=>row.map(c=>c==='.'?'.':'S').join('')),source.map(row=>[...row].reverse().join('')));for(const [board,pose]of [[b,a.default],[b,a.adjusted],[locked,a.next]]){assert(fits(board,pose),key+' landing');assert(!fits(board,{...pose,y:pose.y+1}),key+' grounded');}for(const f of s.frames.filter(f=>f.animate))for(let t=0;t<=f.ticks;t++)assert(fits(C.compose({...f,active:undefined},18),C.frameAt(f,t).active),key+' lesson');const clean=global.TetrisCourse.clean(s);for(const f of clean.frames)if(f.active)assert(fits(C.compose({...f,active:undefined},18),f.active),key+' clean');assert.deepEqual(clean.frames.findLast(f=>f.active).active,a.next);assert.deepEqual(C.normalize(C.compact(s)),s);const attempt=new Attempt(s);attempt.active=C.clone(a.adjusted);attempt.lock();attempt.advance(C.ENTRY_DELAY*1000/C.HZ);if(key==='adjustment-so-tuck'){attempt.active=C.clone(s.frames.find(f=>f.step==='6a').active);assert(attempt.input('right'));assert.deepEqual(attempt.active,a.next);assert.equal(clean.frames.filter(f=>f.active?.type==='O'&&f.buttons.includes('Right')).length,1);}else attempt.active=C.clone(a.next);attempt.lock();assert(attempt.correct&&attempt.done);}});

test('Dengler closes Good but Situational and three Dicey adjustments have safe mirrored paths',()=>{const defs=[["adjustment-dengler-choke","Dengler: Choke thing",["....SSSSS.","....SSSSS.","S...SSSSS.","SS.SSSSSS.","SSSSSSSSS."],{"type":"T","x":6,"y":14,"rotation":0},{"type":"T","x":7,"y":13,"rotation":3},{"type":"S","x":6,"y":14,"rotation":1},"Stand T beside the pocket to leave a vertical landing for S.","Good but Situational"],["adjustment-amogus-dengler","Amogus / Dengler thing",["SSSS......","SSSSS...S.","SSSSS...S."],{"type":"S","x":3,"y":14,"rotation":0},{"type":"S","x":4,"y":13,"rotation":1},{"type":"J","x":2,"y":15,"rotation":1},"Stand S to support the next J when its other landings are awkward.","Dicey"],["adjustment-five-and-below","Five and Below",["........S.",".......SS.","SSS.S.SSS.","SSSSSSSSS.","SSSSSSSSS."],{"type":"L","x":6,"y":13,"rotation":0},{"type":"L","x":8,"y":12,"rotation":1},{"type":"O","x":5,"y":12,"rotation":0},"Stand L at the wall to leave a landing for O beside it.","Dicey"],["adjustment-australian-tucks","Australian tucks",["SSSSSSS...","SSSSSS....","SSSSSS....","SSSSSS...."],{"type":"L","x":1,"y":15,"rotation":1},{"type":"L","x":2,"y":15,"rotation":1},{"type":"O","x":0,"y":15,"rotation":0},"Tuck L right beneath the overhang, then tuck O right into the pocket it creates.","Dicey"]];for(const [key,title,source,def,adj,next,description,section]of defs){const s=C.normalize(require('../situations/'+key+'.js')),a=s.adjustment,b=C.compose(s.frames[0],18),locked=C.compose({board:b,active:a.adjusted},18);assert.equal(s.section,section);assert.deepEqual(b.slice(-source.length).map(row=>row.map(c=>c==='.'?'.':'S').join('')),source.map(row=>[...row].reverse().join('')));for(const [board,pose]of [[b,a.default],[b,a.adjusted],[locked,a.next]]){assert(fits(board,pose),key+' landing');assert(!fits(board,{...pose,y:pose.y+1}),key+' grounded');}for(const f of s.frames.filter(f=>f.animate))for(let t=0;t<=f.ticks;t++)assert(fits(C.compose({...f,active:undefined},18),C.frameAt(f,t).active),key+' lesson');const clean=global.TetrisCourse.clean(s);for(const f of clean.frames)if(f.active)assert(fits(C.compose({...f,active:undefined},18),f.active),key+' clean');assert.deepEqual(clean.frames.findLast(f=>f.active).active,a.next);assert.deepEqual(C.normalize(C.compact(s)),s);const attempt=new Attempt(s);attempt.active=C.clone(a.adjusted);attempt.lock();attempt.advance(C.ENTRY_DELAY*1000/C.HZ);if(key==='adjustment-so-tuck'){attempt.active=C.clone(s.frames.find(f=>f.step==='6a').active);assert(attempt.input('right'));assert.deepEqual(attempt.active,a.next);assert.equal(clean.frames.filter(f=>f.active?.type==='O'&&f.buttons.includes('Right')).length,1);}else attempt.active=C.clone(a.next);attempt.lock();assert(attempt.correct&&attempt.done);}});

test('Australian tucks executes one right tuck for each piece in playback and practice',()=>{const s=C.normalize(require('../situations/adjustment-australian-tucks.js')),clean=global.TetrisCourse.clean(s),attempt=new Attempt(s);for(const [type,pre,goal]of [['L',s.frames.find(f=>f.step==='5').active,s.adjustment.adjusted],['O',s.frames.find(f=>f.step==='6a').active,s.adjustment.next]]){assert.equal(clean.frames.filter(f=>f.active?.type===type&&f.buttons.includes('Right')).length,1);attempt.active=C.clone(pre);assert(attempt.input('right'));assert.deepEqual(attempt.active,goal);attempt.lock();if(type==='L')attempt.advance(C.ENTRY_DELAY*1000/C.HZ);}assert(attempt.correct&&attempt.done);});

test('Doubletuck, Noro JL burn and Null Adjustment preserve their mirrored stacks and safe lesson paths',()=>{const defs=[["adjustment-l-doubletuck","L doubletuck (Ori: J doubletuck)",[".S........","SS........","S.........","SSSSSSSSS.","SSSSSSSSS."],{"type":"J","x":6,"y":11,"rotation":2},{"type":"J","x":7,"y":11,"rotation":0},{"type":"L","x":6,"y":13,"rotation":1},"Place J above the pocket, then tuck L right, turn it, and tuck right again.","Dicey"],["adjustment-noro-jl-burn","Noro JL burn (Ori: Noro LJ burn)",["...S......","S.SS......","SSSS......","SSSSS.....","SSSSSSS...","SSSSSSS...","SSSSSS....","SSSSSS....","SSSSSSSS..","SSSSSSSSS.","SSSSSSSSS."],{"type":"J","x":-1,"y":15,"rotation":3},{"type":"J","x":1,"y":12,"rotation":0},{"type":"L","x":0,"y":11,"rotation":0},"Lay J across the low ledge, then place L flat to burn two rows.","Dicey"],["adjustment-null","Null Adjustment",["SSSSS.....","SSSSSSS...","SSSSSSSSS.","SSSSSSSSS."],{"type":"L","x":0,"y":13,"rotation":3},{"type":"L","x":2,"y":13,"rotation":0},{"type":"J","x":0,"y":13,"rotation":3},"Adjust L for J: the two placements produce the same shape as the default sequence.","Memes/Anti-Adjustments"]];for(const [key,title,source,def,adj,next,description,section]of defs){const s=C.normalize(require('../situations/'+key+'.js')),a=s.adjustment,b=C.compose(s.frames[0],18),locked=C.compose({board:b,active:a.adjusted},18);assert.equal(s.section,section);assert.deepEqual(b.slice(-source.length).map(row=>row.map(c=>c==='.'?'.':'S').join('')),source.map(row=>[...row].reverse().join('')));for(const [board,pose]of [[b,a.default],[b,a.adjusted],[locked,a.next]]){assert(fits(board,pose),key+' landing');assert(!fits(board,{...pose,y:pose.y+1}),key+' grounded');}for(const f of s.frames.filter(f=>f.animate))for(let t=0;t<=f.ticks;t++)assert(fits(C.compose({...f,active:undefined},18),C.frameAt(f,t).active),key+' lesson');const clean=global.TetrisCourse.clean(s);for(const f of clean.frames)if(f.active)assert(fits(C.compose({...f,active:undefined},18),f.active),key+' clean');assert.deepEqual(C.normalize(C.compact(s)),s);const attempt=new Attempt(s);attempt.active=C.clone(a.adjusted);attempt.lock();attempt.advance(C.ENTRY_DELAY*1000/C.HZ);attempt.active=C.clone(a.next);attempt.lock();assert(attempt.correct&&attempt.done);}});
test('L doubletuck performs right, B, right before locking into its final pocket',()=>{const s=C.normalize(require('../situations/adjustment-l-doubletuck.js')),attempt=new Attempt(s);attempt.active=C.clone(s.adjustment.adjusted);attempt.lock();attempt.advance(C.ENTRY_DELAY*1000/C.HZ);attempt.active=C.clone(s.frames.filter(f=>f.lessonStage===6&&f.animate).at(-3).animationFrom);for(const input of ['right','b','right'])assert(attempt.input(input));assert.deepEqual(attempt.active,s.adjustment.next);attempt.lock();assert(attempt.done&&attempt.correct);const actions=global.TetrisCourse.clean(s).frames.filter(f=>f.active?.type==='L'&&f.buttons.length);assert.deepEqual(actions.slice(-3).map(f=>f.buttons),[['Right'],['B'],['Right']]);assert.equal(actions.slice(-3).filter(f=>f.buttons.includes('Right')).length,2);});
test('Noro JL burns two rows and shows the collapsed stack after the native animation',()=>{const s=C.normalize(require('../situations/adjustment-noro-jl-burn.js')),clear=s.frames.find(f=>f.clear);assert.deepEqual(clear.clearRows,[12,13]);assert.equal(clear.ticks,C.LINE_CLEAR.ticks);const after=C.clearAfterBoard(clear,18);assert.deepEqual(C.compose(s.frames.find(f=>f.step==='7'),18),after);assert.deepEqual(C.compose(global.TetrisCourse.clean(s).frames.at(-1),18),after);const attempt=new Attempt(s);attempt.active=C.clone(s.frames.find(f=>f.step==='5').active);assert(attempt.input('b'));assert(attempt.input('right'));assert.deepEqual(attempt.active,s.adjustment.adjusted);attempt.lock();attempt.advance(C.ENTRY_DELAY*1000/C.HZ);attempt.active=C.clone(s.adjustment.next);attempt.lock();assert.equal(attempt.totalRows,2);assert(attempt.correct&&attempt.done);});
test('Null Adjustment ends with exactly the same occupied shape as its default L followed by J',()=>{const s=C.normalize(require('../situations/adjustment-null.js')),base=C.compose({...s.frames[0],active:undefined},18),defaultNext={type:'J',x:2,y:13,rotation:2},def=C.compose({board:base,active:s.adjustment.default},18);assert(fits(def,defaultNext));const expected=C.compose({board:def,active:defaultNext},18);assert.deepEqual(C.compose(s.frames.find(f=>f.step==='7'),18).map(row=>row.map(c=>c!=='.')),expected.map(row=>row.map(c=>c!=='.')));assert.equal(C.fullRows(expected).length,0);});

test('Dog bar, Bar Vits and Gerald Tuck mirror the source with safe grounded two-piece sequences',()=>{const defs=[["adjustment-bar-in-10","Bar in 1: Dog bar (Ori: Bar in 10)",["SSSSSSSS..","SSSSSSSS..","SSSSSSSS..","SSSSSSSS.."],{"type":"I","x":0,"y":14,"rotation":1},{"type":"I","x":-1,"y":14,"rotation":1},{"type":"I","x":0,"y":14,"rotation":1},"Place the first I against the wall, leaving the adjacent column for the next I and a Tetris."],["adjustment-bar-vits","Bar Vits",["...SSSSS..","SSSSSSSS..","SSSSSSSS..","SSSSSSSS.."],{"type":"I","x":0,"y":14,"rotation":1},{"type":"I","x":1,"y":11,"rotation":0},{"type":"I","x":-1,"y":14,"rotation":1},"Lay I flat above the pocket, then stand the next I against the wall."],["adjustment-gerald-tuck","Gerald Tuck",["S.........","SSS.S.S.S.","SSSSSSSSS."],{"type":"J","x":7,"y":13,"rotation":1},{"type":"J","x":7,"y":12,"rotation":0},{"type":"O","x":6,"y":13,"rotation":0},"Lay J above the pocket, then tuck O right twice underneath it."]];for(const [key,title,source]of defs){const s=C.normalize(require('../situations/'+key+'.js')),a=s.adjustment,b=C.compose({...s.frames[0],active:undefined},18),locked=C.compose({board:b,active:a.adjusted},18);assert.equal(s.section,'Memes/Anti-Adjustments');assert.deepEqual(b.slice(-source.length).map(row=>row.map(c=>c==='.'?'.':'S').join('')),source.map(row=>[...row].reverse().join('')));for(const [board,pose]of [[b,a.default],[b,a.adjusted],[locked,a.next]]){assert(fits(board,pose),key+' landing');assert(!fits(board,{...pose,y:pose.y+1}),key+' grounded');}for(const f of s.frames.filter(f=>f.animate))for(let t=0;t<=f.ticks;t++)assert(fits(C.compose({...f,active:undefined},18),C.frameAt(f,t).active),key+' lesson');const clean=global.TetrisCourse.clean(s);for(const f of clean.frames)if(f.active)assert(fits(C.compose({...f,active:undefined},18),f.active),key+' clean');assert.deepEqual(C.normalize(C.compact(s)),s);const attempt=new Attempt(s);attempt.active=C.clone(a.adjusted);attempt.lock();attempt.advance(C.ENTRY_DELAY*1000/C.HZ);attempt.active=C.clone(a.next);attempt.lock();assert(attempt.correct&&attempt.done);}});
test('Dog bar keeps both vertical ROM segment patterns and ends in the native four-row clear',()=>{const s=C.normalize(require('../situations/adjustment-bar-in-10.js')),clear=s.frames.find(f=>f.clear),tiles=C.visualTiles(clear,18);assert.deepEqual(clear.clearRows,[14,15,16,17]);for(const [x,y,id]of C.pieceLayout('I',1))for(const column of [0,1])assert.equal(tiles[14+y][column],id);const after=C.clearAfterBoard(clear,18);assert(after.flat().every(c=>c==='.'));assert.deepEqual(C.compose(s.frames.at(-1),18),after);assert.deepEqual(C.compose(global.TetrisCourse.clean(s).frames.at(-1),18),after);const a=new Attempt(s);a.active=C.clone(s.adjustment.adjusted);a.lock();a.advance(C.ENTRY_DELAY*1000/C.HZ);a.active=C.clone(s.adjustment.next);a.lock();assert.equal(a.totalRows,4);assert(a.correct&&a.done);});
test('Gerald Tuck executes two distinct right tucks with O after its descent',()=>{const s=C.normalize(require('../situations/adjustment-gerald-tuck.js')),a=new Attempt(s);a.active=C.clone(s.adjustment.adjusted);a.lock();a.advance(C.ENTRY_DELAY*1000/C.HZ);a.active=C.clone(s.frames.find(f=>f.step==='6a').active);assert(a.input('right'));assert.equal(a.active.x,5);assert(a.input('right'));assert.deepEqual(a.active,s.adjustment.next);a.lock();assert(a.correct&&a.done);assert.deepEqual(s.frames.filter(f=>f.lessonStage===6&&['6b','6c'].includes(f.step)).map(f=>f.buttons),[['Right'],['Right']]);const last=global.TetrisCourse.clean(s).frames.filter(f=>f.active?.type==='O'&&f.buttons.length).slice(-2);assert.deepEqual(last.map(f=>f.buttons),[['Right'],['Right']]);});

test('every adjustment variant animates all completed rows and continues on the collapsed stack',()=>{let checked=0;for(const original of C.demos().filter(s=>s.chapter==='Adjustments')){const variants=original.adjustment.alternatives?.map(a=>C.normalize(global.TetrisCourse.variant(original,a.type)))||[original];for(const s of variants){checked++;const a=new Attempt(s);a.active=C.clone(s.adjustment.adjusted);a.lock();const firstRows=a.rows;assert.equal(s.frames.filter(f=>f.clear&&f.lessonStage===5).reduce((n,f)=>n+f.clearRows.length,0),firstRows,s.title+' first clear');a.advance((firstRows?C.LINE_CLEAR.ticks:C.ENTRY_DELAY)*1000/C.HZ);assert(a.fits(s.adjustment.next),s.title+' next fits after clear');a.active=C.clone(s.adjustment.next);a.lock();assert.equal(s.frames.filter(f=>f.clear&&f.lessonStage===6).reduce((n,f)=>n+f.clearRows.length,0),a.rows,s.title+' second clear');assert(a.done&&a.correct);const final=C.collapseRows(a.board,C.fullRows(a.board)),clean=global.TetrisCourse.clean(s);assert.deepEqual(C.compose(clean.frames.at(-1),18),final,s.title+' clean final stack');for(const clear of s.frames.filter(f=>f.clear))assert.equal(clear.ticks,C.LINE_CLEAR.ticks);assert.deepEqual(C.normalize(C.compact(s)),s);}}assert(checked>80);});

test('Pump Fake mirrors the reference: a flat I shelf followed by the hook-filling L',()=>{const s=C.normalize(require('../situations/adjustment-pump-fake.js')),a=s.adjustment,b=C.compose({...s.frames[0],active:undefined},18);assert.deepEqual(a.default,{type:'I',x:5,y:12,rotation:1});assert.deepEqual(a.adjusted,{type:'I',x:1,y:11,rotation:0});assert.deepEqual(a.next,{type:'L',x:5,y:13,rotation:1});assert(!fits(C.compose({board:b,active:a.default},18),a.next),'default vertical I occupies the next L gap');const final=C.compose({board:C.compose({board:b,active:a.adjusted},18),active:a.next},18);assert.deepEqual(final.slice(12).map(r=>r.join('')),['.......LLL','.IIIILLLLL','.LLLLLLLLL','.LLLLLLLLL','.LLLLLLLLL','.LLLLLLLLL']);for(let y=14;y<18;y++)assert.equal(final[y][0],'.');for(let x=0;x<10;x++){let occupied=false;for(let y=0;y<18;y++){if(final[y][x]!=='.')occupied=true;else assert(!occupied,'no holes beneath either piece');}}assert.deepEqual(s.frames.find(f=>f.step==='6b').buttons,['A']);assert.equal(C.nativeTurn('L',0,'a'),1);assert(s.frames.filter(f=>f.lessonStage===5&&f.active).every(f=>f.active.rotation===0),'I stays flat throughout its placement');});

test('Waterfall keeps only the mirrored NES J-next example and leaves no covered holes',()=>{const q=require('../js/stack-quality'),scene=C.normalize(require('../situations/adjustment-waterfall.js')),a=scene.adjustment,board=C.compose({...scene.frames[0],active:undefined},18);assert(!a.alternatives?.length,'the unsupported J-next arrangement must not be selectable');assert.equal(a.next.type,'L');assert.deepEqual([...new Set(C.cells('I',a.default.rotation).map(([x])=>a.default.x+x+1))],[10]);assert.deepEqual([...new Set(C.cells('I',a.adjusted.rotation).map(([x])=>a.adjusted.x+x+1))],[8]);const first=C.compose({board,active:a.adjusted},18),both=C.compose({board:first,active:a.next},18);assert.equal(q.analyze(first).holes.count,0);assert.equal(q.analyze(both).holes.count,0);assert.deepEqual([...new Set(C.cells('L',a.next.rotation).map(([x])=>a.next.x+x+1))].sort((a,b)=>a-b),[9,10]);assert(global.TetrisCourse.clean(scene).frames.length>0);});

test('Corrected adjustment defaults do not introduce covered holes and both tuck targets finish cleanly',()=>{
 const H=require('../js/placement-hint'),cases=[['o-z-sisyphus',{type:'O',x:3,y:14,rotation:0}],['vert-s-for-l',{type:'S',x:2,y:12,rotation:0}],['five-and-below',{type:'L',x:6,y:13,rotation:0}],['australian-tucks',{type:'L',x:1,y:16,rotation:2}],['l-doubletuck',{type:'J',x:6,y:14,rotation:2}]];
 for(const[key,expected]of cases){const scene=C.normalize(require('../situations/adjustment-'+key+'.js')),a=scene.adjustment,base=C.compose({...scene.frames[0],active:undefined},18);assert.deepEqual(a.default,expected,key+' default');assert(H.features(C.compose({board:base,active:a.default},18)).holes<=H.features(base).holes,key+' no added holes');assert(H.plan(base,C.spawn(a.default.type),a.default,{gravityFrames:53}),key+' reachable default');const first=H.apply(base,a.adjusted).board;assert.equal(H.features(C.compose({board:first,active:a.next},18)).holes,0,key+' clean pair');for(const frame of global.TetrisCourse.clean(scene).frames)if(frame.active)assert(fits(C.compose({...frame,active:undefined},18),frame.active),key+' clean playback');}
 for(const[key,target]of [['vert-s-for-l',{type:'L',x:0,y:12,rotation:3}],['five-and-below',{type:'O',x:6,y:12,rotation:0}]]){const scene=C.normalize(require('../situations/adjustment-'+key+'.js')),a=scene.adjustment;assert.deepEqual(a.next,target);const last=scene.frames.findLast(f=>f.lessonStage===6&&f.animate),pre={...target,x:target.x-1};assert.deepEqual(last.animationFrom,pre);assert.deepEqual(last.active,target);assert.deepEqual(last.buttons,['Right']);const attempt=new Attempt(scene);attempt.active={...a.adjusted};attempt.lock();attempt.advance(C.ENTRY_DELAY*1000/C.HZ);attempt.active=pre;assert(attempt.input('right'));assert.deepEqual(attempt.active,target);attempt.lock();assert(attempt.correct);}
});
